"use client";

import React, { useState } from "react";

interface BookmarkFormProps {
  initialData?: {
    title: string;
    url: string;
    in_public: boolean;
  };
  onSubmit: (data: { title: string; url: string; in_public: boolean }) => void;
  isLoading?: boolean;
}

export const BookmarkForm: React.FC<BookmarkFormProps> = ({
  initialData,
  onSubmit,
  isLoading = false,
}) => {
  const [formData, setFormData] = useState({
    title: initialData?.title || "",
    url: initialData?.url || "",
    in_public: initialData?.in_public ?? false,
